/**
 * An entry's country, when the country is all that is known of where it is (`countryCode` of the contract, issue #290: a photograph
 * without a geotag). Pure. The country is named and framed on the globe; it is never a point and no place lists the entry.
 *
 * The globe frames GROUPS, and the country groups are generated by the private export from the places (their slugs are not authored),
 * so an entry names its country by ISO code and this module finds the group: the `country` group that most of the places with that code
 * sit in (walking up from each place). No such group (no published place in that country) means the country is named but not framed.
 */
import type { PublishedGroup } from "@catalyst/schemas";
import { countryName } from "~/globe/engine/country-names";

export { countryName };

export interface EntryCountry {
  /** ISO 3166-1 alpha-2, as published. */
  code: string;
  /** The country group's name when there is one (the globe's own label), else the platform's English name, else the code. */
  name: string;
  /** `/?country=BR`: the home page framed on the country. Absent when no group can be framed. */
  href?: string;
}

/** The query parameter the home page frames a country by. */
export const COUNTRY_PARAM = "country";

export const countryPath = (code: string) => `/?${COUNTRY_PARAM}=${code}`;

/** The country code of a home page address (`?country=BR`), or null when there is none or it is not a code. */
export function parseCountryParam(search: string): string | null {
  const value = new URLSearchParams(search).get(COUNTRY_PARAM)?.trim().toUpperCase() ?? "";
  return /^[A-Z]{2}$/.test(value) ? value : null;
}

/** The `country` group that holds most of the places of that country, or null. Ties: the group listed first. */
export function countryGroupOf(
  code: string,
  places: readonly { countryCode?: string | undefined; group?: string | undefined }[],
  groups: readonly Pick<PublishedGroup, "slug" | "kind" | "parent">[],
): string | null {
  const bySlug = new Map(groups.map((g) => [g.slug, g]));
  const votes = new Map<string, number>();
  for (const p of places) {
    if (p.countryCode !== code) continue;
    const seen = new Set<string>();
    for (let cur = p.group; cur !== undefined && !seen.has(cur); cur = bySlug.get(cur)?.parent) {
      seen.add(cur);
      const g = bySlug.get(cur);
      if (g?.kind === "country") {
        votes.set(g.slug, (votes.get(g.slug) ?? 0) + 1);
        break;
      }
    }
  }
  let best: string | null = null;
  let most = 0;
  for (const g of groups) {
    const n = votes.get(g.slug) ?? 0;
    if (n > most) [best, most] = [g.slug, n];
  }
  return best;
}

/** The country of an entry as the pages show it, or undefined when the entry names none. */
export function entryCountry(
  code: string | undefined,
  places: readonly { countryCode?: string | undefined; group?: string | undefined }[],
  groups: readonly Pick<PublishedGroup, "slug" | "kind" | "parent" | "name">[],
): EntryCountry | undefined {
  if (!code) return undefined;
  const slug = countryGroupOf(code, places, groups);
  const group = slug ? groups.find((g) => g.slug === slug) : undefined;
  return { code, name: group?.name ?? countryName(code) ?? code, ...(group ? { href: countryPath(code) } : {}) };
}
